// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { SideToggle } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Actions/SideToggle)

figma.connect(SideToggle, FIGMA_NODE_URL, {
  props: {
    value: figma.enum('value', { 'buy': 'buy', 'sell': 'sell' }),
    defaultValue: figma.enum('defaultValue', { 'buy': 'buy', 'sell': 'sell' }),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
  },
  example: ({ value, defaultValue, size }) => (
    <SideToggle value={value} defaultValue={defaultValue} size={size}></SideToggle>
  ),
});
